#!/usr/bin/env python3
# Generates publicsession.seed.sql and publicsession.cases.json (fictional data only) for the public session page.
#   python3 apps/api/testdata/tools/gen-publicsession-fixtures.py apps/api/internal/publicreads/testdata
# Then rerun capture-publicsession.test.mjs to refresh publicsession.golden.json. Output is committed; change this script, not the output.
import json, sys

OUT = sys.argv[1]
def q(s):
    if s is None:
        return "NULL"
    return "'" + s.replace("'", "''") + "'"

def uid(prefix, n):
    return f"{prefix}000000-0000-4000-8000-{n:012x}"

CLUB = lambda n: uid("e1", n)
PLAYER = lambda n: uid("e2", n)
CP = lambda n: uid("e3", n)
SESS = lambda n: uid("e4", n)
SP = lambda n: uid("e5", n)
WL = lambda n: uid("e6", n)
PUB = lambda n: uid("e7", n)
COURT = lambda n: uid("e8", n)
STREAM = lambda n: uid("e9", n)
CMD = lambda n: uid("ea", n)
FIXED = "TIMESTAMPTZ '2026-11-01 00:00:00+00'"

sql = []
w = sql.append
w("""-- Fictional clubs, players, sessions, rosters, waitlists, courts, streams and publications for the public
-- session page characterization (GET /api/public-sessions/{slug}, Queue's handler `public-session.page`).
-- Applied on top of the Prisma migrations, which already seed the PH locations. Generated by apps/api/testdata/tools/gen-publicsession-fixtures.py; rerun apps/api/testdata/tools/capture-publicsession.test.mjs after any change. Every timestamp is fixed:
-- the page carries the session's updated_at, so the golden must be byte-stable.
-- Foreign key checks are off for this load (some rows deliberately point at nothing, to prove the page
-- tolerates them); CHECK constraints still apply.
BEGIN;
SET LOCAL session_replication_role = replica;
""")

