P = "/api/public-sessions/"
def esc(s):
    from urllib.parse import quote
    return quote(s, safe="")
cases = []
def case(name, path, scenario="base"):
    cases.append({"name": name, "scenario": scenario, "path": path})
for n, s in S.items():
    case("session_" + str(n) + "_" + s["slug"][:24].replace("-", "_"), P + s["slug"])
